{
  "name": "opencode-railway-sandbox",
  "version": "0.3.1",
  "description": "Give OpenCode agents a Railway sandbox: run subagents, builds, and previews in Railway VMs instead of your laptop",
  "type": "module",
  "license": "MIT",
  "exports": {
    ".": "./src/index.ts",
    "./rpc": "./src/rpc.ts",
    "./gui-experimental": "./dist/gui-experimental.cjs"
  },
  "files": [
    "src",
    "dist",
    "README.md",
    "SECURITY.md",
    "docs",
    "LICENSE"
  ],
  "dependencies": {
    "@opencode/plugin": ">=2.3.0 <3",
    "railway": "^3.17.0"
  },
  "devDependencies": {
    "@types/bun": "latest",
    "solid-js": "^1.9",
    "typescript": "^5.9.0",
    "vite": "^7",
    "vite-plugin-solid": "^2.11"
  },
  "scripts": {
    "build": "vite build",
    "dev": "vite build --watch",
    "test": "bun test",
    "typecheck": "tsc -p .",
    "prepublishOnly": "vite build"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "railway",
    "sandbox",
    "remote-agents"
  ],
  "repository": {
    "type": "git",
    "url": "git+https://github.com/m-abdelwahab/opencode-railway-sandbox.git"
  },
  "engines": {
    "node": ">=22"
  },
  "publishConfig": {
    "access": "public",
    "provenance": true
  },
  "bugs": {
    "url": "https://github.com/m-abdelwahab/opencode-railway-sandbox/issues"
  },
  "homepage": "https://github.com/m-abdelwahab/opencode-railway-sandbox#readme"
}
